import{_ as o,C as n,o as t,c as i,a2 as a,b as c,w as s,a as p,E as r,a3 as l}from"./chunks/framework.BvnCBqQl.js";const m=JSON.parse('{"title":"第 2 章 Dify 架构鸟瞰","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/02-dify-architecture.md","filePath":"chapters/02-dify-architecture.md","lastUpdated":1791442702000}'),h={name:"chapters/02-dify-architecture.md"};function g(k,e,y,u,b,f){const d=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="第-2-章-dify-架构鸟瞰" tabindex="-1">第 2 章 Dify 架构鸟瞰 <a class="header-anchor" href="#第-2-章-dify-架构鸟瞰" aria-label="Permalink to &quot;第 2 章 Dify 架构鸟瞰&quot;">​</a></h1><blockquote><p>本章目标：知道 Dify 由哪些进程和服务组成、后端代码怎么分层、前端代码在哪；在本机把 Dify 跑起来。 前置：第 1 章。对应代码：Dify <code>docker/</code>、<code>api/</code>、<code>web/</code>。</p></blockquote><h2 id="_2-1-先看部署-dify-由哪些服务组成" tabindex="-1">2.1 先看部署：Dify 由哪些服务组成 <a class="header-anchor" href="#_2-1-先看部署-dify-由哪些服务组成" aria-label="Permalink to &quot;2.1 先看部署：Dify 由哪些服务组成&quot;">​</a></h2><p>理解一个平台，最快的入口是它的 <code>docker-compose</code>。打开 <code>docker/docker-compose.yaml</code>，核心服务如下（行号为该文件中的位置）：</p><table tabindex="0"><thead><tr><th>服务</th><th>行号</th><th>是什么</th><th>mini-dify 对应</th></tr></thead><tbody><tr><td><code>api</code></td><td>227</td><td>Flask 后端，提供控制台 API / Service API / Web API</td><td><code>api</code>（FastAPI）</td></tr><tr><td><code>worker</code></td><td>306</td><td>Celery Worker：文档索引、异步工作流、邮件、追踪上报……</td><td><code>worker</code>（Celery）</td></tr><tr><td><code>worker_beat</code></td><td>353</td><td>Celery Beat：定时任务调度</td><td><code>scheduler</code></td></tr><tr><td><code>web</code></td><td>387</td><td>Next.js 前端</td><td><code>web</code>（Vite 构建 + nginx）</td></tr><tr><td><code>db_postgres</code> / <code>db_mysql</code></td><td>425 / 462</td><td>业务数据库</td><td><code>db</code>（Postgres）</td></tr><tr><td><code>redis</code></td><td>492</td><td>缓存、Celery Broker、分布式锁、跨进程事件</td><td><code>redis</code></td></tr><tr><td><code>sandbox</code></td><td>510</td><td>代码执行沙箱（<code>dify-sandbox</code>，seccomp 隔离）</td><td>子进程 + rlimit（第 27 章）</td></tr><tr><td><code>plugin_daemon</code></td><td>573</td><td>插件守护进程：独立运行所有插件（模型、工具……）</td><td>进程内插件加载器（第 26 章）</td></tr><tr><td><code>agent_backend</code></td><td>660</td><td>新一代 Agent 运行时（<code>dify-agent</code>）</td><td>第 21 章介绍</td></tr><tr><td><code>ssrf_proxy</code></td><td>727</td><td>Squid 代理，拦截对内网地址的请求</td><td>进程内 SSRF 检查（第 27 章）</td></tr><tr><td><code>nginx</code></td><td>772</td><td>统一入口，反向代理 api / web</td><td><code>web</code> 里的 nginx</td></tr><tr><td><code>weaviate</code> / <code>qdrant</code> / <code>pgvector</code> / <code>milvus</code> …</td><td>817 起</td><td>向量数据库，二选一</td><td>SQLite/Postgres 存向量 + numpy（第 23 章）</td></tr></tbody></table><p>画成图：</p>',6)),(t(),c(l,null,{default:s(()=>[r(d,{id:"mermaid-205",class:"mermaid",graph:"flowchart%20TB%0A%20%20User((%E6%B5%8F%E8%A7%88%E5%99%A8%20%2F%20API%20%E8%B0%83%E7%94%A8%E6%96%B9))%20--%3E%20Nginx%5Bnginx%5D%0A%20%20Nginx%20--%3E%20Web%5Bweb%3A%20Next.js%5D%0A%20%20Nginx%20--%3E%20API%5Bapi%3A%20Flask%5D%0A%20%20API%20--%3E%20PG%5B(Postgres)%5D%0A%20%20API%20--%3E%20Redis%5B(Redis)%5D%0A%20%20API%20--%3E%20VDB%5B(%E5%90%91%E9%87%8F%E5%BA%93)%5D%0A%20%20API%20--%3E%20Storage%5B(%E6%96%87%E4%BB%B6%E5%AD%98%E5%82%A8%3A%20%E6%9C%AC%E5%9C%B0%2FS3%2FOSS)%5D%0A%20%20API%20--%20%22Celery%20%E4%BB%BB%E5%8A%A1%22%20--%3E%20Redis%0A%20%20Redis%20--%3E%20Worker%5Bworker%3A%20Celery%5D%0A%20%20Beat%5Bworker_beat%5D%20--%3E%20Redis%0A%20%20Worker%20--%3E%20PG%20%26%20VDB%20%26%20Storage%0A%20%20API%20--%3E%20Sandbox%5Bsandbox%3A%20%E4%BB%A3%E7%A0%81%E6%89%A7%E8%A1%8C%5D%0A%20%20API%20%3C--%3E%20Plugin%5Bplugin_daemon%3A%20%E6%A8%A1%E5%9E%8B%2F%E5%B7%A5%E5%85%B7%E6%8F%92%E4%BB%B6%5D%0A%20%20API%20--%3E%20SSRF%5Bssrf_proxy%5D%20--%3E%20Internet((%E5%A4%96%E9%83%A8%20HTTP))%0A%20%20API%20%3C--%3E%20Agent%5Bagent_backend%3A%20dify-agent%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>从这张图可以读出几个架构决策：</p><ol><li><strong>API 无状态、可水平扩展</strong>：会话、任务状态都在 Postgres / Redis 里，任何一个 API 实例都能处理任何请求。</li><li><strong>重活交给 Worker</strong>：文档索引动辄几分钟，绝不能占着 HTTP 请求。</li><li><strong>不受信的代码隔离运行</strong>：用户写的 Python、第三方插件、用户配置的 HTTP 请求，都跑在单独的进程或服务里。</li><li><strong>向量库可插拔</strong>：Dify 支持近 30 种向量库，通过工厂模式切换（<code>api/core/rag/datasource/vdb/vector_factory.py</code>）。</li></ol><h2 id="_2-2-后端代码分层" tabindex="-1">2.2 后端代码分层 <a class="header-anchor" href="#_2-2-后端代码分层" aria-label="Permalink to &quot;2.2 后端代码分层&quot;">​</a></h2><p><code>api/</code> 的顶层目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api/</span></span>
<span class="line"><span>├── app.py / app_factory.py   # 创建 Flask 应用，初始化扩展</span></span>
<span class="line"><span>├── configs/                  # 配置（pydantic-settings），通过 dify_config 读取</span></span>
<span class="line"><span>├── controllers/              # ① HTTP 层：路由、参数解析、序列化</span></span>
<span class="line"><span>│   ├── console/              #    控制台（编辑器、设置）用的 API</span></span>
<span class="line"><span>│   ├── service_api/          #    对外开放的 API（/v1，用 App Key 鉴权）</span></span>
<span class="line"><span>│   ├── web/                  #    分享出去的 WebApp 用的 API</span></span>
<span class="line"><span>│   ├── mcp/                  #    把应用暴露成 MCP Server</span></span>
<span class="line"><span>│   ├── trigger/              #    Webhook 等触发器入口</span></span>
<span class="line"><span>│   └── inner_api/            #    给 plugin_daemon 等内部服务回调</span></span>
<span class="line"><span>├── services/                 # ② 业务编排：一个用例一个函数</span></span>
<span class="line"><span>├── core/                     # ③ 领域核心：应用生成、工作流、Agent、RAG、工具、模型……</span></span>
<span class="line"><span>├── models/                   # ④ SQLAlchemy 模型（表结构）</span></span>
<span class="line"><span>├── repositories/             #    数据访问抽象（可切换存储后端）</span></span>
<span class="line"><span>├── tasks/                    #    Celery 任务</span></span>
<span class="line"><span>├── extensions/               #    基础设施初始化：db、redis、celery、storage、otel……</span></span>
<span class="line"><span>├── libs/                     #    与业务无关的工具函数</span></span>
<span class="line"><span>└── migrations/               #    Alembic 数据库迁移</span></span></code></pre></div><p>调用方向是<strong>单向</strong>的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>controllers  →  services  →  core  →  models / repositories / extensions</span></span>
<span class="line"><span>（解析请求）     （编排用例）    （领域逻辑）     （存储与基础设施）</span></span></code></pre></div><p>Dify 在 <code>api/AGENTS.md</code> 里把这条规则写成了明确的约定（节选）：</p><blockquote><p>Keep transport parsing and serialization in controllers, orchestration in services, and domain policy in its domain owner. ... Keep <code>libs/</code> business-agnostic ... Scope tenant-owned reads and writes by the complete owner chain, and propagate <code>tenant_id</code> across every affected layer. Keep write transactions explicit and bounded. Do not perform external I/O inside an open transaction ... route outbound HTTP through the existing SSRF-safe owner in <code>core.helper.ssrf_proxy</code>.</p></blockquote><p>这几条在本书后面都会遇到，而且 mini-dify 会<strong>亲身踩到其中两条的坑</strong>：第 28 章的定时器因为在事务里发起了另一次写操作而锁库（违反了“不要在开着的事务里做外部 I/O”）；第 24 章所有查询都必须带上 <code>tenant_id</code>。</p><blockquote><p>注：<code>api/AGENTS.md</code> 还提到 <code>core/</code> 正在被逐步拆分，新代码不再放进 <code>core/</code>。本书引用的大多数核心逻辑目前仍在 <code>core/</code> 下，读源码时以本书给出的路径为准。</p></blockquote><h3 id="一个请求在分层中的样子" tabindex="-1">一个请求在分层中的样子 <a class="header-anchor" href="#一个请求在分层中的样子" aria-label="Permalink to &quot;一个请求在分层中的样子&quot;">​</a></h3><p>以“运行草稿工作流”为例：</p><table tabindex="0"><thead><tr><th>层</th><th>文件</th><th>做什么</th></tr></thead><tbody><tr><td>controller</td><td><code>api/controllers/console/app/workflow.py:1149</code> <code>DraftWorkflowRunApi.post</code></td><td>解析请求体、校验登录和权限、调用 service，把结果包成 HTTP 响应</td></tr><tr><td>service</td><td><code>api/services/app_generate_service.py:101</code> <code>AppGenerateService.generate</code></td><td>限流、按应用类型选 Generator</td></tr><tr><td>core</td><td><code>api/core/app/apps/workflow/app_generator.py</code> → <code>app_runner.py</code> → <code>core/workflow/workflow_entry.py</code></td><td>准备变量池、构建图、跑引擎、转换事件</td></tr><tr><td>models</td><td><code>api/models/workflow.py</code> <code>Workflow</code>、<code>WorkflowRun</code>、<code>WorkflowNodeExecutionModel</code></td><td>草稿、运行记录、节点执行记录</td></tr></tbody></table><p>第 3 章会把这条链路完整走一遍。</p><h2 id="_2-3-前端代码在哪" tabindex="-1">2.3 前端代码在哪 <a class="header-anchor" href="#_2-3-前端代码在哪" aria-label="Permalink to &quot;2.3 前端代码在哪&quot;">​</a></h2><p><code>web/</code> 是 Next.js（App Router）项目。和本书相关的目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>web/</span></span>
<span class="line"><span>├── app/</span></span>
<span class="line"><span>│   ├── (commonLayout)/        # 控制台页面：应用列表、编辑器、知识库……</span></span>
<span class="line"><span>│   ├── (shareLayout)/         # 分享出去的 WebApp 页面</span></span>
<span class="line"><span>│   └── components/</span></span>
<span class="line"><span>│       ├── workflow/          # ★ 工作流画布编辑器（全书前端部分的主角）</span></span>
<span class="line"><span>│       │   ├── index.tsx      #   画布入口（基于 reactflow）</span></span>
<span class="line"><span>│       │   ├── nodes/         #   每种节点：node.tsx（画布上）+ panel.tsx（配置面板）+ default.ts</span></span>
<span class="line"><span>│       │   ├── store/         #   Zustand 状态</span></span>
<span class="line"><span>│       │   ├── hooks/         #   交互逻辑：拖拽、连线、同步草稿、运行事件处理……</span></span>
<span class="line"><span>│       │   └── run/           #   运行面板、追踪</span></span>
<span class="line"><span>│       ├── workflow-app/      # 工作流应用页的外壳（草稿同步、运行入口）</span></span>
<span class="line"><span>│       ├── datasets/          # 知识库</span></span>
<span class="line"><span>│       └── tools/             # 工具管理</span></span>
<span class="line"><span>└── service/                   # 调用后端的函数，base.ts 里有 ssePost</span></span></code></pre></div><h2 id="_2-4-其他重要组成" tabindex="-1">2.4 其他重要组成 <a class="header-anchor" href="#_2-4-其他重要组成" aria-label="Permalink to &quot;2.4 其他重要组成&quot;">​</a></h2><ul><li><strong>graphon</strong>：图执行引擎，独立的 PyPI 包（<code>api/pyproject.toml</code> 第 48 行：<code>&quot;graphon==0.7.0&quot;</code>）。把引擎拆成独立包，说明 Dify 把它当作一个<strong>通用组件</strong>：它不知道“应用”“租户”“数据库”这些概念，只负责“给我一张图和一个变量池，我把它跑完并吐出事件”。第 9 章会细读它。</li><li><strong>dify-agent / agenton</strong>（<code>dify-agent/</code>）：新一代 Agent 运行时，用“层（Layer）组合”的方式构建 Agent，作为 <code>agent_backend</code> 服务独立部署。第 21 章介绍。</li><li><strong>dify-agent-runtime</strong>（<code>dify-agent-runtime/</code>）：Go 写的 Agent 执行环境组件。</li><li><strong>cli/</strong>：命令行工具 <code>difyctl</code>；<strong>sdks/</strong>：各语言的 Service API SDK；<strong>e2e/</strong>：Cucumber + Playwright 端到端测试。</li></ul><h2 id="_2-5-动手-在本机跑起-dify" tabindex="-1">2.5 动手：在本机跑起 Dify <a class="header-anchor" href="#_2-5-动手-在本机跑起-dify" aria-label="Permalink to &quot;2.5 动手：在本机跑起 Dify&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/langgenius/dify.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dify/docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 等所有容器 healthy 后，打开 http://localhost/install 创建管理员</span></span></code></pre></div><p><code>docker/README.md</code> 写明需要 Docker Compose v2.24.0 以上。首次启动要拉不少镜像，请耐心等待。</p><p><strong>用 Dify 做一个 3 节点工作流</strong>，后面所有章节都会以它为参照：</p><ol><li>设置 → 模型供应商：配置一个模型（OpenAI / DeepSeek / Ollama 都可以）；</li><li>工作室 → 创建空白应用 → 选择 <strong>工作流</strong>；</li><li>画布上默认已有“开始”节点。在开始节点添加输入字段 <code>query</code>（段落）；</li><li>点开始节点右侧的 <code>+</code>，添加 <strong>LLM</strong> 节点，用户提示词写 <code>{{#开始.query#}}</code>（在输入框里键入 <code>{</code> 或 <code>/</code> 可以弹出变量选择）；</li><li>在 LLM 后添加 <strong>结束</strong> 节点，输出变量 <code>result</code> 选择 <code>LLM.text</code>；</li><li>点右上角“运行”，输入一段话，观察：节点依次变绿，结果区的文字逐字出现。</li></ol><p><strong>打开浏览器开发者工具 → Network</strong>，再运行一次，找到 <code>workflows/draft/run</code> 这个请求，看它的 Response。你会看到一行行的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: {&quot;event&quot;: &quot;workflow_started&quot;, &quot;task_id&quot;: &quot;...&quot;, &quot;workflow_run_id&quot;: &quot;...&quot;, &quot;data&quot;: {...}}</span></span>
<span class="line"><span>data: {&quot;event&quot;: &quot;node_started&quot;, ...}</span></span>
<span class="line"><span>data: {&quot;event&quot;: &quot;text_chunk&quot;, ...}</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>data: {&quot;event&quot;: &quot;workflow_finished&quot;, ...}</span></span></code></pre></div><p><strong>这就是第 3 章要追踪的那条链路的出口。</strong> 记住这几个事件名，mini-dify 会原样实现它们。</p><h2 id="_2-6-从零实现-mini-dify-的同构骨架" tabindex="-1">2.6 从零实现：mini-dify 的同构骨架 <a class="header-anchor" href="#_2-6-从零实现-mini-dify-的同构骨架" aria-label="Permalink to &quot;2.6 从零实现：mini-dify 的同构骨架&quot;">​</a></h2><p>mini-dify 的目录（v1.0）和 Dify 一一对应：</p><table tabindex="0"><thead><tr><th>Dify</th><th>mini-dify</th><th>说明</th></tr></thead><tbody><tr><td><code>api/controllers/console/</code></td><td><code>backend/app/api/apps.py</code>、<code>datasets.py</code>、<code>tools.py</code>、<code>auth.py</code></td><td>控制台 API</td></tr><tr><td><code>api/controllers/service_api/</code>、<code>web/</code>、<code>trigger/</code></td><td><code>backend/app/api/service.py</code></td><td>/v1、WebApp、Webhook</td></tr><tr><td><code>api/controllers/mcp/</code></td><td><code>backend/app/mcp/server.py</code></td><td>MCP Server</td></tr><tr><td><code>api/services/</code></td><td><code>backend/app/services/</code></td><td>草稿/发布、DSL、单步调试</td></tr><tr><td><code>api/core/app/apps/</code></td><td><code>backend/app/apps/</code></td><td>Generator、事件转换、持久化</td></tr><tr><td>graphon</td><td><code>backend/app/workflow/</code></td><td>图引擎 + 节点</td></tr><tr><td><code>api/core/agent/</code>、<code>core/tools/</code>、<code>core/mcp/</code></td><td><code>backend/app/agent/</code>、<code>tools/</code>、<code>mcp/</code></td><td></td></tr><tr><td><code>api/core/rag/</code></td><td><code>backend/app/rag/</code></td><td></td></tr><tr><td><code>api/models/</code></td><td><code>backend/app/models.py</code></td><td>一个文件放下所有表</td></tr><tr><td><code>api/tasks/</code>、<code>extensions/ext_celery.py</code></td><td><code>backend/app/tasks/</code></td><td>Celery、事件总线、命令通道</td></tr><tr><td><code>web/app/components/workflow/</code></td><td><code>frontend/src/workflow/</code></td><td>画布编辑器</td></tr></tbody></table><p>刻意的简化：</p><ul><li>Flask → <strong>FastAPI</strong>：Pydantic 请求模型和依赖注入写起来更短。但我们的 handler 依然是<strong>同步函数</strong>，和 Dify 一样用“工作线程 + 队列”来做流式输出，原理完全相同。</li><li>Next.js → <strong>Vite + React</strong>：画布编辑器是纯客户端组件，不需要服务端渲染。</li><li>Postgres → 开发时用 <strong>SQLite</strong>，部署时用 Postgres（通过 <code>DATABASE_URL</code> 切换）。</li><li>不做数据库迁移，启动时 <code>create_all()</code> 建表。</li></ul><h2 id="_2-7-练习" tabindex="-1">2.7 练习 <a class="header-anchor" href="#_2-7-练习" aria-label="Permalink to &quot;2.7 练习&quot;">​</a></h2><ol><li><strong>巩固</strong>：画出 Dify 中“用户上传一个 PDF 到知识库”涉及的服务和它们之间的调用（提示：api → redis → worker → 向量库）。</li><li><strong>扩展</strong>：在 Dify 的运行请求里找到 <code>ping</code> 事件，算算它多久出现一次，猜猜它的作用（第 3 章揭晓）。</li><li><strong>读源码</strong>：打开 <code>api/app_factory.py</code>，列出 Flask 应用初始化时加载的扩展（<code>ext_*.py</code>）及顺序，说说为什么 <code>ext_database</code> 要在 <code>ext_celery</code> 之前。</li></ol><h2 id="_2-8-延伸阅读" tabindex="-1">2.8 延伸阅读 <a class="header-anchor" href="#_2-8-延伸阅读" aria-label="Permalink to &quot;2.8 延伸阅读&quot;">​</a></h2><ul><li><code>docker/README.md</code>：部署说明、环境变量组织方式（<code>.env</code> + <code>envs/*.env.example</code>）</li><li><code>api/AGENTS.md</code>：后端分层与编码约定</li><li><code>docker/docker-compose.middleware.yaml</code>：只起中间件（db/redis/向量库），本地开发 Dify 源码时用</li></ul>`,37))])}const _=o(h,[["render",g]]);export{m as __pageData,_ as default};
